// Classify the message: photo, text meal or a command. Dates use the workflow timezone.
const m = $json.message || {};
const text = String(m.text || m.caption || '').trim();
const cmd = (text.match(/^\/(\w+)(@\w+)?/) || [])[1]?.toLowerCase() || '';
const arg = cmd ? text.replace(/^\/\w+(@\w+)?\s*/, '') : text;
let kind = 'help', error = '';
if (m.photo) kind = 'photo';
else if (['today', 'week', 'undo'].includes(cmd)) kind = cmd;
else if (cmd === 'fix') { kind = arg ? 'fix' : 'help'; if (!arg) error = 'Tell me what to change, e.g. /fix it was half a portion'; }
else if (cmd === 'goal') {
  const n = (arg.match(/\d+(\.\d+)?/g) || []).map(Number);
  if (n.length && n[0] >= 800 && n[0] <= 6000) kind = 'goal';
  else error = 'Use /goal kcal protein carbs fat, e.g. /goal 2000 150 200 70 (macros optional)';
  var goal = { kcal: n[0] || 0, protein_g: n[1] || '', carbs_g: n[2] || '', fat_g: n[3] || '' };
}
else if (cmd) kind = 'help';
else if (text) kind = 'text';
const when = DateTime.fromSeconds(m.date || Math.floor(Date.now() / 1000));
return [{ json: {
  kind, arg, error, goal: goal || null,
  chat_id: m.chat?.id, user_id: String(m.from?.id ?? ''), user_name: m.from?.first_name || '',
  message_id: m.message_id, date: when.toFormat('yyyy-MM-dd'), time: when.toFormat('HH:mm'),
} }];

// Find this user's most recent meal that is not undone (for /undo and /fix)
const p = $('Parse message').first().json;
const rows = $input.all().map(i => i.json)
  .filter(r => r.meal_id && String(r.user_id) === p.user_id && r.status !== 'undone')
  .sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`) || (a.row_number || 0) - (b.row_number || 0));
const last = rows[rows.length - 1];
if (!last) return [{ json: { ...p, found: false } }];
const previous = { dish: last.dish, portion: last.portion, calories_kcal: Number(last.calories_kcal),
  protein_g: Number(last.protein_g), carbs_g: Number(last.carbs_g), fat_g: Number(last.fat_g), notes: last.notes };
return [{ json: { ...p, found: true, meal_id: last.meal_id, meal_date: last.date, meal_time: last.time,
  source: last.source || 'text', previous } }];

// Build the sheet row. A /fix keeps the original meal_id, date and time so the row is updated in place.
const p = $('Parse message').first().json;
const o = $json.output;
let last = null;
try { last = $('Find my last meal').first().json; } catch (e) { last = null; }
const isFix = p.kind === 'fix' && last && last.found;
const num = v => Math.round(Number(v) || 0);
return [{ json: {
  meal_id: isFix ? last.meal_id : `${p.user_id}-${p.message_id}`,
  date: isFix ? last.meal_date : p.date, time: isFix ? last.meal_time : p.time,
  user_id: p.user_id, user_name: p.user_name,
  dish: o.dish, portion: o.portion, calories_kcal: num(o.calories_kcal), protein_g: num(o.protein_g),
  carbs_g: num(o.carbs_g), fat_g: num(o.fat_g), confidence: o.confidence,
  source: isFix ? last.source : (p.kind === 'photo' ? 'photo' : 'text'),
  status: isFix ? 'corrected' : 'logged', notes: o.notes || '',
} }];

// Reply for every action: what was logged/changed, then today vs targets, or a 7-day view for /week
const p = $('Parse message').first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const n = v => Math.round(Number(v) || 0);
const rows = $('Read my meals').all().map(i => i.json)
  .filter(r => r.meal_id && String(r.user_id) === p.user_id && r.status !== 'undone');
const t = $('Read my targets').all().map(i => i.json).find(r => String(r.user_id) === p.user_id) || {};
const sum = (list, k) => n(list.reduce((a, r) => a + (Number(r[k]) || 0), 0));
const day = d => rows.filter(r => String(r.date) === d);
let head = '';
if (['photo', 'text', 'fix'].includes(p.kind)) {
  const m = $('Prepare log row').first().json;
  head = `${p.kind === 'fix' ? '✏️ Updated' : '🍽'} <b>${esc(m.dish)}</b> (${esc(m.portion)})\n` +
    `≈ ${m.calories_kcal} kcal · P ${m.protein_g} g · C ${m.carbs_g} g · F ${m.fat_g} g\n` +
    `Confidence: ${esc(m.confidence)}. ${esc(m.notes)}\n\n`;
} else if (p.kind === 'undo') {
  head = `↩️ Removed <b>${esc($('Find my last meal').first().json.previous.dish)}</b> from your log.\n\n`;
} else if (p.kind === 'goal') {
  head = `🎯 Daily targets saved: ${n(p.goal.kcal)} kcal` +
    (p.goal.protein_g ? ` · P ${p.goal.protein_g} g · C ${p.goal.carbs_g || '-'} g · F ${p.goal.fat_g || '-'} g` : '') +
    `. You'll get a summary at 9pm.\n\n`;
}
let body;
if (p.kind === 'week') {
  const days = [...Array(7)].map((_, i) => DateTime.fromISO(p.date).minus({ days: 6 - i }).toFormat('yyyy-MM-dd'));
  const prev = [...Array(7)].map((_, i) => DateTime.fromISO(p.date).minus({ days: 13 - i }).toFormat('yyyy-MM-dd'));
  const kc = days.map(d => sum(day(d), 'calories_kcal'));
  const logged = kc.filter(k => k > 0);
  const avg = logged.length ? n(logged.reduce((a, b) => a + b, 0) / logged.length) : 0;
  const pk = prev.map(d => sum(day(d), 'calories_kcal')).filter(k => k > 0);
  const pavg = pk.length ? n(pk.reduce((a, b) => a + b, 0) / pk.length) : 0;
  const goal = n(t.kcal);
  const lines = days.map((d, i) => {
    const flag = !kc[i] ? '·' : goal ? (kc[i] > goal * 1.1 ? '🔺' : kc[i] < goal * 0.8 ? '🔻' : '✅') : '';
    return `${DateTime.fromISO(d).toFormat('ccc dd')}  ${String(kc[i]).padStart(5)} kcal ${flag}`;
  });
  body = `<b>Last 7 days</b>\n<pre>${lines.join('\n')}</pre>\nAverage on logged days: <b>${avg} kcal</b>` +
    (goal ? ` (target ${goal})` : '') + `\nDays logged: ${logged.length}/7` +
    (pavg ? `\nTrend vs previous 7 days: ${avg >= pavg ? '+' : ''}${avg - pavg} kcal/day` : '') +
    `\nAvg protein: ${logged.length ? n(days.reduce((a, d) => a + sum(day(d), 'protein_g'), 0) / logged.length) : 0} g`;
} else {
  const today = day(p.date);
  const line = (label, k, tk, unit) => {
    const got = sum(today, k), goal = n(t[tk]);
    if (!goal) return `${label}: ${got} ${unit}`;
    const left = goal - got;
    return `${label}: ${got} / ${goal} ${unit} (${left >= 0 ? left + ' left' : -left + ' over'})`;
  };
  body = `<b>Today</b> (${today.length} meal${today.length === 1 ? '' : 's'})\n` +
    [line('Calories', 'calories_kcal', 'kcal', 'kcal'), line('Protein', 'protein_g', 'protein_g', 'g'),
     line('Carbs', 'carbs_g', 'carbs_g', 'g'), line('Fat', 'fat_g', 'fat_g', 'g')].join('\n') +
    (t.kcal ? '' : '\n\nSet daily targets with /goal 2000 150 200 70');
}
return [{ json: { chat_id: p.chat_id, text: head + body } }];

// One summary per user in Targets (skips evening_summary = no): today vs target and the 7-day average
const n = v => Math.round(Number(v) || 0);
const today = DateTime.now().toFormat('yyyy-MM-dd');
const week = [...Array(7)].map((_, i) => DateTime.now().minus({ days: i }).toFormat('yyyy-MM-dd'));
const meals = $('Read all meals').all().map(i => i.json).filter(r => r.meal_id && r.status !== 'undone');
const out = [];
for (const t of $('Read everyone\'s targets').all().map(i => i.json)) {
  if (!t.user_id || String(t.evening_summary).toLowerCase() === 'no') continue;
  const mine = meals.filter(r => String(r.user_id) === String(t.user_id));
  const tm = mine.filter(r => String(r.date) === today);
  const s = k => n(tm.reduce((a, r) => a + (Number(r[k]) || 0), 0));
  const daily = week.map(d => n(mine.filter(r => String(r.date) === d).reduce((a, r) => a + (Number(r.calories_kcal) || 0), 0))).filter(k => k > 0);
  out.push({ json: {
    chat_id: t.chat_id || t.user_id, user_name: t.user_name || '', meals_today: tm.length,
    dishes: tm.map(r => r.dish).join('; '),
    kcal: s('calories_kcal'), protein_g: s('protein_g'), carbs_g: s('carbs_g'), fat_g: s('fat_g'),
    kcal_target: n(t.kcal), protein_target: n(t.protein_g), carbs_target: n(t.carbs_g), fat_target: n(t.fat_g),
    avg_7d: daily.length ? n(daily.reduce((a, b) => a + b, 0) / daily.length) : 0, days_logged_7d: daily.length,
  } });
}
return out;

